import{boot,e,field,select,editAttrs}from'../creative-kit/ui.js?v=0.12.0';import{make,validate,apply,markdown,VERDICTS,cell,FIELDS}from'./state.js?v=0.12.0';
function ideaCard(i){return `<article class="map-idea" data-drag-id="${e(i.id)}"><div class="card-top"><button class="text-button" data-action="edit-idea" data-id="${e(i.id)}">${e(i.title)}</button><button class="drag-handle" data-drag-handle data-action="move-menu" data-id="${e(i.id)}" aria-label="Move ${e(i.title)}">⠿</button></div><p>${e(i.mechanism||'Describe the working idea.')}</p><button class="text-button" data-action="move-menu" data-id="${e(i.id)}">Move ↗</button></article>`;}
function render(w){const[n,m]=w.selected.split('|'),gap=w.gaps[w.selected]||{verdict:'open',reason:''},occupied=new Set(w.ideas.filter(i=>i.need&&i.method).map(i=>cell(i.need,i.method)));return `<div class="section-head"><div><h2>Which combinations have you not tried?</h2><p>${occupied.size} of ${w.needs.length*w.methods.length} combinations contain ideas. Empty space is a question, not evidence of an opportunity.</p></div><div class="toolbar"><button data-action="axes" data-axis="needs">Edit needs</button><button data-action="axes" data-axis="methods">Edit mechanisms</button><button data-action="add-idea">+ Unplaced idea</button></div></div><p class="hint">Scroll the map sideways to explore other mechanisms. Move opens every destination without dragging.</p><div class="map-scroll" tabindex="0" aria-label="Needs by mechanisms map; scroll sideways on small screens"><table class="territory-map"><thead><tr><th scope="col">NEED ↓ / MECHANISM →</th>${w.methods.map(m=>`<th scope="col">${e(m.label)}</th>`).join('')}</tr></thead><tbody>${w.needs.map(n=>`<tr><th scope="row">${e(n.label)}</th>${w.methods.map(m=>{const key=cell(n.id,m.id),items=w.ideas.filter(i=>i.need===n.id&&i.method===m.id);return `<td class="map-cell ${key===w.selected?'selected':''} ${items.length>1?'crowded':''}" data-drop-id="${e(key)}"><div class="cell-heading"><span>${items.length} ${items.length===1?'idea':'ideas'}</span><button data-action="select" data-cell="${e(key)}" aria-label="Explore ${e(n.label)} using ${e(m.label)}">${items.length?'Inspect':'Explore gap'}</button></div>${items.map(ideaCard).join('')||`<div class="gap-mark">${w.gaps[key]?.verdict==='reason'?'Reason recorded':'?'}</div>`}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><div class="territory-lower"><section class="panel gap-notebook"><p class="eyebrow">ONE COMBINATION TO EXAMINE</p><h2>${e(w.needs.find(x=>x.id===n).label)} <span>×</span> ${e(w.methods.find(x=>x.id===m).label)}</h2>${select('gap-verdict','Why might this space be empty?',gap.verdict,VERDICTS,editAttrs('gap','','verdict'))}${field('gap-reason','Your reasoning',gap.reason,editAttrs('gap','','reason'),'Was it overlooked, excluded by a shared assumption, or empty for a good reason?')}<button class="primary" data-action="add-idea" data-cell="${e(w.selected)}">Create an idea in this space</button></section><section class="panel" data-drop-id="unplaced"><h2>Not placed yet</h2><p class="hint">Keep ideas whose useful axes are still unclear. Drag to a cell, or use Move. Renaming an axis preserves every idea attached to it.</p><div class="stack">${w.ideas.filter(i=>i.need===null||i.method===null).map(ideaCard).join('')||'<div class="empty">Drop an idea here to unplace it.</div>'}</div><details><summary>Look for shared assumptions</summary>${w.ideas.map(i=>`<p><strong>${e(i.title)}:</strong> ${e(i.assumption||'Assumption not written yet.')}</p>`).join('')}</details></section></div>`;}
function edit(id,k){const i=k.w().ideas.find(i=>i.id===id);k.open(FIELDS.map((f,index)=>field(`idea-${f}`,['Idea name','How does it work?','What assumption does it depend on?','What small test would make it worth keeping?'][index],i[f],editAttrs('ideas',id,f))).join('')+`<div class="toolbar"><button class="primary" data-action="close">Done</button><button class="delete" data-action="remove-idea" data-id="${e(id)}">Remove idea</button></div>`,'Develop the possibility');}
function axes(axis,k){k.open(k.w()[axis].map(x=>field(`axis-${x.id}`,axis==='needs'?'Need':'Mechanism',x.label,editAttrs(axis,x.id,'label'),'',1)).join('')+`<div class="toolbar"><button data-action="add-axis" data-axis="${axis}" ${k.w()[axis].length>=6?'disabled':''}>+ ${axis==='needs'?'Need':'Mechanism'}</button><button class="primary" data-action="close">Done</button></div><p class="hint">Labels change the framing. Attached ideas and gap notes stay in place.</p>`,'Change the map axes');}
boot({route:'territory',code:'S08',title:'Unexplored territory',description:'Map ideas by the needs they serve and the mechanisms they use. Investigate the empty combinations.',make,validate,apply,markdown,render,drop:(id,to,k)=>k.act({type:'move',id,cell:to}),handle:(a,d,k)=>{if(a==='edit-idea')edit(d.id,k);else if(a==='add-idea'){const id=k.uid();if(k.act({type:a,id,cell:d.cell}))edit(id,k);}else if(a==='axes')axes(d.axis,k);else if(a==='add-axis'){k.close();if(k.act({type:a,axis:d.axis,id:k.uid()}))axes(d.axis,k);}else if(a==='select')k.act({type:a,cell:d.cell},{checkpoint:false});else if(a==='move-menu')k.open('<div class="dialog-options">'+k.w().needs.flatMap(n=>k.w().methods.map(m=>`<button data-action="place" data-id="${e(d.id)}" data-cell="${e(cell(n.id,m.id))}">${e(n.label)} × ${e(m.label)}</button>`)).join('')+`<button data-action="place" data-id="${e(d.id)}" data-cell="unplaced">Keep unplaced</button></div>`,'Move this idea');else if(a==='place'){k.close();k.act({type:'move',id:d.id,cell:d.cell});}else if(a==='remove-idea'){k.close();k.act({type:a,id:d.id});}}});
